import{_ as a,c as n,d as e,Z as o}from"./chunks/framework.B0uuYL3Y.js";const l="/microarch/boom-lsu.png",b=JSON.parse('{"title":"加载怎样从存储队列拿到数据","description":"对照 BOOM 的访存单元，从队列字段和字节掩码推导加载何时转发、等待或重试。","frontmatter":{"title":"加载怎样从存储队列拿到数据","description":"对照 BOOM 的访存单元，从队列字段和字节掩码推导加载何时转发、等待或重试。","date":"2026-11-25","tags":["微架构安全","访存队列","存储转发","乱序执行"],"book":"microarch-00-intro"},"headers":[],"relativePath":"posts/microarch-03d-load-store.md","filePath":"posts/microarch-03d-load-store.md"}'),t={name:"posts/microarch-03d-load-store.md"};function p(r,s,c,d,i,y){return n(),e("div",null,s[0]||(s[0]=[o('<p>程序先向地址 <code>0x1000</code> 写入 9，接着从同一位置读回。如果这笔写入还留在核心里，L1 缓存中存的仍是 5，后面的读怎样取得 9？答案取决于两个操作所访问的字节，以及较早的写入在队列里已经准备到哪一步。本文以 BOOM 的加载／存储单元为例，从队列项一直追踪到寄存器写回。</p><nav class="table-of-contents"><ul><li><a href="#lsu-structure">加载与存储单元的结构</a><ul><li><a href="#lsu-entries">队列项里存着什么</a></li></ul></li><li><a href="#lsu-forward">一次完整的存储转发</a></li><li><a href="#lsu-overlap">怎样判断字节重叠和转发来源</a><ul><li><a href="#用代码检查选择顺序">用代码检查选择顺序</a></li></ul></li><li><a href="#lsu-replay">存储地址迟到，加载怎样重试</a></li><li><a href="#参考文献">参考文献</a></li></ul></nav><h2 id="lsu-structure" tabindex="-1">加载与存储单元的结构 <a class="header-anchor" href="#lsu-structure" aria-label="Permalink to &quot;加载与存储单元的结构 {#lsu-structure}&quot;">​</a></h2><p>加载／存储单元（Load/Store Unit，LSU）一端接执行流水线，另一端接数据缓存。加载和存储进入执行后端时，先在相应队列里留位置。等基址寄存器就绪，执行单元计算有效地址并送入 LSU。TLB 提供<a href="./microarch-02a-translation.html">地址翻译</a>所需的信息，LSU 才能用物理地址比较两条访问是否指向同一处。存储的源数据由另一个寄存器提供，可以独立到达。</p><figure class="lesson-figure"><a href="/microarch/boom-lsu.png" aria-label="放大查看 BOOM 官方加载与存储单元图"><img src="'+l+`" alt="BOOM 官方 LSU 框图，上方是存储队列和加载队列，中间是控制器、TLB 和地址比较逻辑，右侧是数据缓存，底部选择加载的写回数据。" width="820" height="1178" style="filter:grayscale(1);background-color:white;" loading="lazy" decoding="async"></a><figcaption>图 1　BOOM 官方 LSU 框图。上方两张表保存未完成的访存操作。沿左侧转发数据和右侧缓存数据两条线，可以找到底部的写回选择器。点击查看原图。</figcaption></figure><p>图 1 上方，<code>STQ</code> 是存储队列（Store Queue），<code>LDQ</code> 是加载队列（Load Queue）。左侧比较逻辑 <code>Searcher</code> 从两类队列读取地址和状态。它既可以在加载时搜索在先的存储，也可以在存储地址得到翻译后，检查在后的加载是否已经沿错误的依赖关系执行。图右的 <code>Data Cache</code> 是另一条取数路径。缓存命中时，数据阵列直接返回数据。未命中时，由缓存的 <a href="./microarch-01a-mshr.html">MSHR</a> 跟踪缺失的缓存行。转发的数据和缓存返回的数据最终都接到图底部的选择器。</p><h3 id="lsu-entries" tabindex="-1">队列项里存着什么 <a class="header-anchor" href="#lsu-entries" aria-label="Permalink to &quot;队列项里存着什么 {#lsu-entries}&quot;">​</a></h3><p>图中用 <code>addr</code>、<code>data</code> 等短标签指示字段。下面列出本节会用到的 BOOM v3 状态。</p><table tabindex="0"><thead><tr><th>位置</th><th>字段或状态</th><th>在什么情况下改变</th></tr></thead><tbody><tr><td>STQ</td><td>表项有效、<code>addr.valid</code>、<code>addr_is_virtual</code></td><td>分配时先占用表项。计算出虚拟地址后可暂存，翻译成功后才能用物理地址做最终比较</td></tr><tr><td>STQ</td><td><code>data.valid</code>、<code>data</code></td><td>存储的源寄存器值送达后置有效，地址和数据可以分开就绪</td></tr><tr><td>STQ</td><td><code>committed</code>、<code>succeeded</code></td><td>ROB 退休存储时标记已提交，收到缓存完成确认后再标记已完成</td></tr><tr><td>LDQ</td><td><code>addr</code>、<code>addr_is_virtual</code>、<code>st_dep_mask</code></td><td>记录加载的地址与翻译状态。掩码的每一位对应一个可能依赖的较老 STQ 项</td></tr><tr><td>LDQ</td><td><code>executed</code>、<code>succeeded</code></td><td>分别记录向内存侧执行的进度和是否已经取值成功。请求被拒绝可以使加载重新进入等待</td></tr><tr><td>LDQ</td><td><code>forward_std_val</code>、<code>forward_stq_idx</code>、<code>order_fail</code></td><td>保留转发来源的索引和顺序检查结果，供后续检查</td></tr></tbody></table><p><code>st_dep_mask</code> 表示哪些较老存储仍需要考虑。某一位为 1 时，队列项可能连地址都没有。真正是否依赖，还要等地址和访问大小参与比较。相应的存储项完成、退出队列后，它对应的掩码位会清除。</p><h2 id="lsu-forward" tabindex="-1">一次完整的存储转发 <a class="header-anchor" href="#lsu-forward" aria-label="Permalink to &quot;一次完整的存储转发 {#lsu-forward}&quot;">​</a></h2><p>假设一个 RV64 线程修改自己的计数值。<code>x10</code> 和 <code>x13</code> 都指向 <code>0x1000</code>，该位置八字节对齐、可缓存，翻译和权限检查都能通过。L1 初始保存 5，<code>x11</code> 保存准备写入的新值 9。</p><div class="language-asm line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">asm</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">sd   x11, </span><span style="color:#D33682;">0</span><span style="color:#839496;">(x10)   </span><span style="color:#586E75;font-style:italic;"> # S：向 0x1000 写入 8 字节</span></span>
<span class="line"><span style="color:#839496;">ld   x12, </span><span style="color:#D33682;">0</span><span style="color:#839496;">(x13)   </span><span style="color:#586E75;font-style:italic;"> # L：从 0x1000 读取 8 字节</span></span>
<span class="line"><span style="color:#839496;">addi x14, x12, </span><span style="color:#D33682;">1</span><span style="color:#586E75;font-style:italic;">    # I：使用 L 的结果</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>sd</code> 需要两份输入。<code>x10 + 0</code> 给出地址，<code>x11</code> 给出数据。如果 <code>x11</code> 先就绪，存储的数据操作就先填 <code>STQ.data</code>，其地址子操作仍可留在发射窗口。若两个操作数都已就绪，BOOM 可以用一次发射把地址和数据一起送进 LSU。<code>ld</code> 只用基址计算地址，取回的数据再写入为 <code>x12</code> 分配的物理寄存器。</p><table tabindex="0"><thead><tr><th>示例周期</th><th>队列和流水线中的动作</th><th>这时能确定的结果</th></tr></thead><tbody><tr><td>4</td><td>S 的数据送到 STQ，<code>data.valid</code> 置位</td><td>队列里已有 9，尚不知要写到哪里</td></tr><tr><td>6</td><td>S 的地址生成并完成翻译</td><td>可以确定 S 覆盖的物理字节，S 尚未退休</td></tr><tr><td>8</td><td>L 的地址到达比较逻辑，命中 S 的全部八字节</td><td>取消 L 对 L1 的尝试，从 S 转发 9</td></tr><tr><td>9</td><td>I 消费 L 已写回的值</td><td>I 在内部算出 10</td></tr><tr><td>12</td><td>S 到达 ROB 队头并退休</td><td>STQ 项标为已提交，可以按顺序向缓存发送</td></tr><tr><td>14</td><td>本例假定缓存接下 S 的写入</td><td>L1 中该位置更新为 9</td></tr></tbody></table><p>这些周期是题设。第 8 周期的关键在于，缓存仍保留 5 时，转发已经能让同一线程的 L 得到 9。STQ 项的提交标志决定何时允许这笔写入向缓存发送。其他核心何时能观察到写入，还要看<a href="./microarch-01f-coherence.html">一致性协议</a>和架构内存模型。</p><p>如果只把 S 的数据就绪时间从第 4 周期挪到第 10 周期，第 8 周期仍能确定地址重叠。L 因为拿不到 9 而等待，之后重试。如果改的是 <code>x13</code>，让 L 读取 <code>0x1008</code>，S 写到 <code>0x1007</code> 为止，两次访问可以落在同一条缓存行上，却没有共享字节。此时 L 可以继续走缓存取数路径。</p><h2 id="lsu-overlap" tabindex="-1">怎样判断字节重叠和转发来源 <a class="header-anchor" href="#lsu-overlap" aria-label="Permalink to &quot;怎样判断字节重叠和转发来源 {#lsu-overlap}&quot;">​</a></h2><p>比较地址需要回答两件事。访问范围有没有重叠？存储覆盖了加载需要的全部字节吗？BOOM v3 对本节这类普通对齐访问先比较物理地址所属的八字节单元，再由地址低位和访问大小生成字节掩码。掩码第 0 位对应这个单元的最低地址。设读掩码为 <code>R</code>、写掩码为 <code>W</code>，那么 <code>R &amp; W != 0</code> 表示重叠，<code>R &amp; W == R</code> 表示全覆盖。</p><p>以小端存储 <code>0x1122334455667788</code> 为例。地址 <code>0x1000</code> 开始的八个字节依次为 <code>88 77 66 55 44 33 22 11</code>。<code>lwu</code> 从 <code>0x1004</code> 取四字节并零扩展。因此，即使两条指令的起始地址不同，<code>sd</code> 的 <code>0xff</code> 仍完整覆盖 <code>lwu</code> 的 <code>0xf0</code>，可以转发 <code>0x11223344</code>。若存储改为从 <code>0x1004</code> 开始写两字节的 <code>sh</code>，写掩码为 <code>0x30</code>，只能覆盖读掩码 <code>0xf0</code> 的一部分。此时 BOOM v3 的这条转发路径会阻止加载继续取缓存旧值，等重试条件成立后再取数。这里讨论的是单项转发，整个加载最终仍要得到每个字节应有的值。</p><p>如果在例题的 S 之前再插入一条往 <code>0x1000</code> 写 7 的存储 <code>S0</code>，会有两个匹配项。BOOM v3 先根据程序顺序选出在 L 之前最接近 L 的匹配项 S，再确认它能否转发。即使 <code>S0</code> 的 7 早已备好，只要 S 覆盖同一个位置，L 就必须等 S 的 9。若先用就绪与否筛选来源，就会绕过程序中那次实际应生效的写入。</p><h3 id="用代码检查选择顺序" tabindex="-1">用代码检查选择顺序 <a class="header-anchor" href="#用代码检查选择顺序" aria-label="Permalink to &quot;用代码检查选择顺序&quot;">​</a></h3><p>下面的 Python 代码只处理上面已经确定物理地址的例题。列表中的元素代表还在队列里、并且比该加载更早的存储，按程序顺序排列。代码先从较新的项找重叠，再判断全覆盖和数据就绪。缓存数据由两个八字节值组成，偏移 0 和 8 分别对应地址 <code>0x1000</code> 和 <code>0x1008</code>。</p><div class="language-python line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#93A1A1;font-weight:bold;">def</span><span style="color:#268BD2;"> read_from_queue</span><span style="color:#839496;">(cache, stores, offset, size):</span></span>
<span class="line"><span style="color:#839496;">    read_end </span><span style="color:#859900;">=</span><span style="color:#839496;"> offset </span><span style="color:#859900;">+</span><span style="color:#839496;"> size</span></span>
<span class="line"><span style="color:#859900;">    for</span><span style="color:#839496;"> start, width, value </span><span style="color:#859900;">in</span><span style="color:#268BD2;"> reversed</span><span style="color:#839496;">(stores):</span></span>
<span class="line"><span style="color:#839496;">        write_end </span><span style="color:#859900;">=</span><span style="color:#839496;"> start </span><span style="color:#859900;">+</span><span style="color:#839496;"> width</span></span>
<span class="line"><span style="color:#859900;">        if</span><span style="color:#839496;"> write_end </span><span style="color:#859900;">&lt;=</span><span style="color:#839496;"> offset </span><span style="color:#859900;">or</span><span style="color:#839496;"> read_end </span><span style="color:#859900;">&lt;=</span><span style="color:#839496;"> start:</span></span>
<span class="line"><span style="color:#859900;">            continue</span></span>
<span class="line"><span style="color:#859900;">        if</span><span style="color:#839496;"> start </span><span style="color:#859900;">&gt;</span><span style="color:#839496;"> offset </span><span style="color:#859900;">or</span><span style="color:#839496;"> write_end </span><span style="color:#859900;">&lt;</span><span style="color:#839496;"> read_end </span><span style="color:#859900;">or</span><span style="color:#839496;"> value </span><span style="color:#859900;">is</span><span style="color:#B58900;"> None</span><span style="color:#839496;">:</span></span>
<span class="line"><span style="color:#859900;">            return</span><span style="color:#2AA198;"> &quot;wait&quot;</span><span style="color:#839496;">, </span><span style="color:#B58900;">None</span></span>
<span class="line"></span>
<span class="line"><span style="color:#839496;">        data </span><span style="color:#859900;">=</span><span style="color:#839496;"> value.to_bytes(width, </span><span style="color:#2AA198;">&quot;little&quot;</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">        start_in_data </span><span style="color:#859900;">=</span><span style="color:#839496;"> offset </span><span style="color:#859900;">-</span><span style="color:#839496;"> start</span></span>
<span class="line"><span style="color:#859900;">        return</span><span style="color:#2AA198;"> &quot;forward&quot;</span><span style="color:#839496;">, </span><span style="color:#859900;">int</span><span style="color:#839496;">.from_bytes(</span></span>
<span class="line"><span style="color:#839496;">            data[start_in_data : start_in_data </span><span style="color:#859900;">+</span><span style="color:#839496;"> size], </span><span style="color:#2AA198;">&quot;little&quot;</span></span>
<span class="line"><span style="color:#839496;">        )</span></span>
<span class="line"></span>
<span class="line"><span style="color:#859900;">    return</span><span style="color:#2AA198;"> &quot;cache&quot;</span><span style="color:#839496;">, </span><span style="color:#859900;">int</span><span style="color:#839496;">.from_bytes(cache[offset:read_end], </span><span style="color:#2AA198;">&quot;little&quot;</span><span style="color:#839496;">)</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#839496;">cache </span><span style="color:#859900;">=</span><span style="color:#839496;"> (</span><span style="color:#D33682;">5</span><span style="color:#839496;">).to_bytes(</span><span style="color:#D33682;">8</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;little&quot;</span><span style="color:#839496;">) </span><span style="color:#859900;">+</span><span style="color:#839496;"> (</span><span style="color:#D33682;">13</span><span style="color:#839496;">).to_bytes(</span><span style="color:#D33682;">8</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;little&quot;</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">s0 </span><span style="color:#859900;">=</span><span style="color:#839496;"> (</span><span style="color:#D33682;">0</span><span style="color:#839496;">, </span><span style="color:#D33682;">8</span><span style="color:#839496;">, </span><span style="color:#D33682;">7</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">s </span><span style="color:#859900;">=</span><span style="color:#839496;"> (</span><span style="color:#D33682;">0</span><span style="color:#839496;">, </span><span style="color:#D33682;">8</span><span style="color:#839496;">, </span><span style="color:#D33682;">9</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">wait_for_s </span><span style="color:#859900;">=</span><span style="color:#839496;"> (</span><span style="color:#D33682;">0</span><span style="color:#839496;">, </span><span style="color:#D33682;">8</span><span style="color:#839496;">, </span><span style="color:#B58900;">None</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">wide </span><span style="color:#859900;">=</span><span style="color:#839496;"> (</span><span style="color:#D33682;">0</span><span style="color:#839496;">, </span><span style="color:#D33682;">8</span><span style="color:#839496;">, </span><span style="color:#93A1A1;font-weight:bold;">0x</span><span style="color:#D33682;">1122334455667788</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">half </span><span style="color:#859900;">=</span><span style="color:#839496;"> (</span><span style="color:#D33682;">4</span><span style="color:#839496;">, </span><span style="color:#D33682;">2</span><span style="color:#839496;">, </span><span style="color:#93A1A1;font-weight:bold;">0x</span><span style="color:#D33682;">ABCD</span><span style="color:#839496;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> read_from_queue(cache, [s0, s], </span><span style="color:#D33682;">0</span><span style="color:#839496;">, </span><span style="color:#D33682;">8</span><span style="color:#839496;">) </span><span style="color:#859900;">==</span><span style="color:#839496;"> (</span><span style="color:#2AA198;">&quot;forward&quot;</span><span style="color:#839496;">, </span><span style="color:#D33682;">9</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> read_from_queue(cache, [s0, wait_for_s], </span><span style="color:#D33682;">0</span><span style="color:#839496;">, </span><span style="color:#D33682;">8</span><span style="color:#839496;">) </span><span style="color:#859900;">==</span><span style="color:#839496;"> (</span><span style="color:#2AA198;">&quot;wait&quot;</span><span style="color:#839496;">, </span><span style="color:#B58900;">None</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> read_from_queue(cache, [s], </span><span style="color:#D33682;">8</span><span style="color:#839496;">, </span><span style="color:#D33682;">8</span><span style="color:#839496;">) </span><span style="color:#859900;">==</span><span style="color:#839496;"> (</span><span style="color:#2AA198;">&quot;cache&quot;</span><span style="color:#839496;">, </span><span style="color:#D33682;">13</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> read_from_queue(cache, [wide], </span><span style="color:#D33682;">4</span><span style="color:#839496;">, </span><span style="color:#D33682;">4</span><span style="color:#839496;">) </span><span style="color:#859900;">==</span><span style="color:#839496;"> (</span><span style="color:#2AA198;">&quot;forward&quot;</span><span style="color:#839496;">, </span><span style="color:#93A1A1;font-weight:bold;">0x</span><span style="color:#D33682;">11223344</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> read_from_queue(cache, [wide, half], </span><span style="color:#D33682;">4</span><span style="color:#839496;">, </span><span style="color:#D33682;">4</span><span style="color:#839496;">) </span><span style="color:#859900;">==</span><span style="color:#839496;"> (</span><span style="color:#2AA198;">&quot;wait&quot;</span><span style="color:#839496;">, </span><span style="color:#B58900;">None</span><span style="color:#839496;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br></div></div><p>最后一条断言同时检查了两个条件。较新的 <code>half</code> 覆盖了低两个字节，较老的 <code>wide</code> 虽然能提供四字节，但其中低两个字节已经被后写覆盖。整个四字节的加载不能直接取 <code>wide</code>。如果等两条写入都按序进入缓存，读到的四字节应是 <code>cd ab 22 11</code>，即 <code>0x1122abcd</code>。</p><h2 id="lsu-replay" tabindex="-1">存储地址迟到，加载怎样重试 <a class="header-anchor" href="#lsu-replay" aria-label="Permalink to &quot;存储地址迟到，加载怎样重试 {#lsu-replay}&quot;">​</a></h2><p>回到第一段汇编，只把 S 的地址延后。假定第 8 周期 L 发出读请求时，STQ 里已经有 9，却还没有可用于比较的 S 地址。BOOM 可以先让 L 尝试访问缓存。若缓存返回旧值，检查就要等到 S 的物理地址出现。</p><table tabindex="0"><thead><tr><th>示例周期</th><th>已有记录</th><th>下一步怎样处理</th></tr></thead><tbody><tr><td>8</td><td>LDQ 的相关存储掩码还含 S，S 的物理地址未就绪</td><td>L 向 L1 发出尝试性的读请求</td></tr><tr><td>9</td><td>L 已从缓存取得 5</td><td>I 随后可能以 5 为输入算出 6</td></tr><tr><td>11</td><td>S 的物理地址得到确认</td><td>比较逻辑查到已经取值的 L 与 S 重叠，且 L 的 5 来自缓存，报告顺序失败</td></tr><tr><td>重试</td><td>L 和依赖它的年轻结果需要恢复</td><td>L 重新执行，取得 9，I 再算得 10</td></tr></tbody></table><p>第 11 周期的检查方向和第 8 周期不同。年轻的 L 初次取值时搜索较老的 STQ 项。较老的 S 地址就绪后，BOOM v3 反过来搜索已经执行的相关 LDQ 项。如果 L 的值来自比 S 更早的存储，也必须检查这次更近的写入是否被跳过。源码中的 <code>forward_stq_idx</code> 就为这种检查保留了原始来源。顺序失败由核心内部处理，从需要重试的加载恢复执行，已经消费旧值的年轻结果也跟着撤销。这个例题没有权限错误，程序最终仍正常读到 9。</p><details class="details custom-block"><summary>练习：把加载位置移到原存储的后一半</summary><p>回到完整转发的时间线，把 S 的数据换为 <code>0x1122334455667788</code>，把 L 改成从 <code>0x1004</code> 开始的 <code>lwu</code>。第 8 周期应从哪里取数？把 S 改成从 <code>0x1000</code> 开始的四字节 <code>sw</code>，其余保持不变，再判定一次。</p><p>第一次，读掩码是 <code>0xf0</code>，写掩码为 <code>0xff</code>，应从 S 取其高四字节，即 <code>0x11223344</code>。第二次，<code>sw</code> 的写掩码变成 <code>0x0f</code>，与 <code>0xf0</code> 没有交集，L 走缓存路径。两种访问都在同一个八字节单元里，区别由字节掩码给出。</p></details><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://docs.boom-core.org/en/latest/sections/load-store-unit.html" target="_blank" rel="noreferrer">BOOM 加载／存储单元，图 24 和队列工作说明</a></li><li><a href="https://github.com/riscv-boom/riscv-boom/blob/53cf7ac2fff66e1e658fca1d40b783e6c45704ba/docs/figures/lsu.png" target="_blank" rel="noreferrer">图 1 原文件，BOOM 项目固定版本</a> · <a href="/microarch/boom-license.txt">BSD 3-Clause 许可</a></li><li><a href="https://github.com/riscv-boom/riscv-boom/blob/53cf7ac2fff66e1e658fca1d40b783e6c45704ba/src/main/scala/v3/lsu/lsu.scala#L1020" target="_blank" rel="noreferrer">BOOM v3 LSU 源码，队列项、字节掩码、转发优先级与顺序失败检查</a></li><li><a href="https://docs.boom-core.org/en/latest/sections/reorder-buffer.html" target="_blank" rel="noreferrer">BOOM ROB 文档，退休与流水线恢复</a></li><li><a href="https://docs.riscv.org/reference/isa/v20260120/unpriv/mm-eplan.html#loadvalueaxiom" target="_blank" rel="noreferrer">RISC-V RVWMO 说明，加载值与存储转发</a></li></ul><nav class="article-nav" aria-label="系列文章导航"><p><a href="./microarch-03-execution.html" class="article-nav-card article-nav-prev" rel="prev"><span class="article-nav-text"><small>上一篇</small><strong>乱序执行怎样按程序顺序退休</strong></span></a></p><p><a href="./microarch-03a-fetch-prediction.html" class="article-nav-card article-nav-next" rel="next"><span class="article-nav-text"><small>下一篇</small><strong>分支预测器怎样决定下一次取指</strong></span></a></p></nav>`,33)]))}const h=a(t,[["render",p]]);export{b as __pageData,h as default};
